def tilingRibbonEvenKeyCensus(readings, k):
    a=readings
    out=[]
    m=max(a,default=0)
    dp=[0]*(m+1)
    dp[0]=1
    for i in range(1,m+1): dp[i]=dp[i-1]+(dp[i-3] if i>=3 else 0)
    out=[dp[x] for x in a]
